def _locked(self, *, exclusive: bool):
    # A migration killed between its two renames leaves the live path
    # absent and a backup file beside it. Adoption mutates the tree, so
    # readers that observe this state escalate to an exclusive lock.
    if not exclusive and self._needs_adoption():
        exclusive = True
    with st.file_lock(
        self._lock_path(), timeout=self.lock_timeout, shared=not exclusive
    ):
        if exclusive:
