def _entry_fresh(entry: dict, stat: os.stat_result, unit: dict) -> bool:
    """Hot-path freshness with constant read amplification.

    * active/legacy unit: size + mtime + ctime guard (any rewrite
      changes ctime, which cannot be restored);
    * sealed unit: identical stat plus identical preserved window
      material in the manifest -- a manifest-side window edit therefore
      forces the cold path and is reported as corruption, without a
      single sealed byte being hashed on the ordinary path.
    """
    if not Chain._stat_fresh(entry, stat):
        return False
    if unit["sealed"]:
        return entry.get("parts") == unit["parts"]
    return True

